method BinarySearch(a: seq<int>, key: int) returns (idx: int)
  requires Sorted(a)
  ensures -1 <= idx < |a|
  ensures idx >= 0 ==> a[idx] == key
  ensures idx == -1 ==> key !in a
{
  var lo, hi := 0, |a|;
  while lo < hi
    invariant 0 <= lo <= hi <= |a|
    invariant forall i :: 0 <= i < lo ==> a[i] != key
    invariant forall i :: hi <= i < |a| ==> a[i] != key
    decreases hi - lo
  {
    var mid := lo + (hi - lo) / 2;
    if a[mid] < key {
      assert forall i :: 0 <= i <= mid ==> a[i] <= a[mid];
      lo := mid + 1;
    } else if a[mid] > key {
      assert forall i :: mid <= i < |a| ==> a[mid] <= a[i];
      hi := mid;
    } else {
      return mid;
    }
  }
  assert forall i :: 0 <= i < |a| ==> a[i] != key;
  return -1;
}

