method BinarySearch(a: seq<int>, key: int) returns (idx: int)
  requires Sorted(a)
  ensures -1 <= idx < |a|
  ensures idx >= 0 ==> a[idx] == key
  ensures idx == -1 ==> key !in a
{
  var lo := 0;
  var hi := |a|;
  while lo < hi
    invariant 0 <= lo <= hi <= |a|
    invariant forall i :: 0 <= i < lo ==> a[i] < key
    invariant forall i :: hi <= i < |a| ==> a[i] > key
    decreases hi - lo
  {
    var mid := lo + (hi - lo) / 2;
    if a[mid] < key {
      forall i | 0 <= i < mid + 1
        ensures a[i] < key
      {
        if i < mid {
          assert a[i] <= a[mid];
        }
      }
      lo := mid + 1;
    } else if a[mid] > key {
      forall i | mid <= i < |a|
        ensures a[i] > key
      {
        if mid < i {
          assert a[mid] <= a[i];
        }
      }
      hi := mid;
    } else {
      return mid;
    }
  }
  assert forall i :: 0 <= i < |a| ==> a[i] != key;
  return -1;
}

response:
The search keeps a half-open window `[lo, hi)`. Everything left of `lo` is smaller than `key`, and everything from `hi` onward is larger. When the window is empty, `key` cannot be in `a`.

