lemma BinarySearch_AllBeforeLess(s: seq<int>, key: int, mid: int)
  requires Sorted(s)
  requires 0 <= mid < |s|
  requires s[mid] < key
  ensures forall i :: 0 <= i <= mid ==> s[i] < key
{
  reveal Sorted(s);
  forall i | 0 <= i <= mid
    ensures s[i] < key
  {
    if i < mid {
      assert 0 <= i < mid < |s|;
      assert s[i] <= s[mid];
    } else {
      assert i == mid;
    }
  }
}

lemma BinarySearch_AllAfterGreater(s: seq<int>, key: int, mid: int)
  requires Sorted(s)
  requires 0 <= mid < |s|
  requires key < s[mid]
  ensures forall i :: mid <= i < |s| ==> key < s[i]
{
  reveal Sorted(s);
  forall i | mid <= i < |s|
    ensures key < s[i]
  {
    if mid < i {
      assert 0 <= mid < i < |s|;
      assert s[mid] <= s[i];
    } else {
      assert i == mid;
    }
  }
}

method BinarySearch(a: seq<int>, key: int) returns (idx: int)
  requires Sorted(a)
  ensures -1 <= idx < |a|
  ensures idx >= 0 ==> a[idx] == key
  ensures idx == -1 ==> key !in a
{
  var lo := 0;
  var hi := |a|;

  while lo < hi
    invariant 0 <= lo <= hi <= |a|
    invariant forall i :: 0 <= i < lo ==> a[i] < key
    invariant forall i :: hi <= i < |a| ==> key < a[i]
    decreases hi - lo
  {
    var mid := lo + (hi - lo) / 2;
    assert lo <= mid < hi;

    if a[mid] < key {
      BinarySearch_AllBeforeLess(a, key, mid);
      lo := mid + 1;
    } else if key < a[mid] {
      BinarySearch_AllAfterGreater(a, key, mid);
      hi := mid;
    } else {
      assert a[mid] == key;
      idx := mid;
      return;
    }
  }

  assert lo == hi;
  assert forall i :: 0 <= i < |a| ==> a[i] != key by {
    forall i | 0 <= i < |a|
      ensures a[i] != key
    {
      if i < lo {
        assert a[i] < key;
      } else {
        assert hi <= i;
        assert key < a[i];
      }
    }
  }

  assert key !in a;
  idx := -1;
}

