  ensures -1 <= idx < |a|
  ensures idx >= 0 ==> a[idx] == key
  ensures idx == -1 ==> key !in a
{
  var lo := 0;
  var hi := |a|;

  while lo < hi
    invariant 0 <= lo <= hi <= |a|
    invariant forall i :: 0 <= i < lo ==> a[i] < key
    invariant forall i :: hi <= i < |a| ==> key < a[i]
    decreases hi - lo
  {
    var mid := lo + (hi - lo) / 2;
    assert lo <= mid < hi;

    if a[mid] < key {
      forall i | 0 <= i <= mid
        ensures a[i] < key
      {
        if i < mid {
          assert a[i] <= a[mid];
        }
      }
      lo := mid + 1;
    } else if key < a[mid] {
      forall i | mid <= i < |a|
        ensures key < a[i]
      {
        if mid < i {
          assert a[mid] <= a[i];
        }
      }
      hi := mid;
    } else {
      return mid;
    }
  }

  assert lo == hi;
  forall i | 0 <= i < |a|
    ensures a[i] != key
  {
    if i < lo {
      assert a[i] < key;
    } else {
      assert hi <= i;
      assert key < a[i];
    }
  }

  idx := -1;
}

