method Dedup(a: seq<int>) returns (r: seq<int>)
  requires Sorted(a)
  ensures StrictlySorted(r)
  ensures forall x :: x in a <==> x in r
{
  r := [];
  var i := 0;
  while i < |a|
    invariant 0 <= i <= |a|
    invariant StrictlySorted(r)
    invariant forall x :: x in r <==> x in a[..i]
    invariant i == 0 <==> |r| == 0
    invariant i > 0 ==> r[|r|-1] == a[i-1]
  {
    assert a[..i+1] == a[..i] + [a[i]];
    if i == 0 || a[i] != a[i-1] {
      if i > 0 {
        assert a[i-1] <= a[i];
        assert a[i-1] < a[i];
        assert forall k :: 0 <= k < |r| ==> r[k] <= r[|r|-1];
        assert forall k :: 0 <= k < |r| ==> r[k] < a[i];
      }
      var r' := r + [a[i]];
      assert forall k :: 0 <= k < |r| ==> r'[k] == r[k];
      assert r'[|r|] == a[i];
      assert StrictlySorted(r');
      r := r';
    } else {
      assert a[i] == a[i-1];
      assert a[i-1] in a[..i];
      assert a[i] in r;
    }
    i := i + 1;
  }
  assert a[..|a|] == a;
}

