lemma AppendStrict(s: seq<int>, x: int)
  requires StrictlySorted(s)
  requires forall i :: 0 <= i < |s| ==> s[i] < x
  ensures StrictlySorted(s + [x])
{
  forall i, j | 0 <= i < j < |s + [x]|
    ensures (s + [x])[i] < (s + [x])[j]
  {
    if j < |s| {
      assert 0 <= i < j < |s|;
      assert s[i] < s[j];
      assert (s + [x])[i] == s[i];
      assert (s + [x])[j] == s[j];
    } else {
      assert j == |s|;
      assert 0 <= i < |s|;
      assert s[i] < x;
      assert (s + [x])[i] == s[i];
      assert (s + [x])[j] == x;
    }
  }
