method Dedup(a: seq<int>) returns (r: seq<int>)
  requires Sorted(a)
  ensures StrictlySorted(r)
  ensures forall x :: x in a <==> x in r
{
  r := [];
  var i := 0;

  while i < |a|
    invariant 0 <= i <= |a|
    invariant StrictlySorted(r)
    invariant forall x ::
      x in r <==> exists j :: 0 <= j < i && a[j] == x
    decreases |a| - i
  {
    var oldR := r;

    assert StrictlySorted(oldR);
    assert forall x ::
      x in oldR <==> exists j :: 0 <= j < i && a[j] == x;

    if a[i] !in oldR {
      forall k | 0 <= k < |oldR|
        ensures oldR[k] < a[i]
      {
        assert oldR[k] in oldR;
        assert exists j :: 0 <= j < i && a[j] == oldR[k];
        var j :| 0 <= j < i && a[j] == oldR[k];

        assert 0 <= j < i < |a|;
        assert a[j] <= a[i];
        assert oldR[k] != a[i];
        assert oldR[k] < a[i];
      }

      AppendStrict(oldR, a[i]);
      r := oldR + [a[i]];

      forall x
        ensures x in r <==>
          exists j :: 0 <= j < i + 1 && a[j] == x
      {
