method IsSorted(a: seq<int>) returns (b: bool)
  ensures b <==> Sorted(a)
{
  var i := 0;

  while i < |a|
    invariant 0 <= i <= |a|
    invariant forall x, y :: 0 <= x < y < |a| && x < i ==> a[x] <= a[y]
    decreases |a| - i
  {
    var j := i + 1;

    while j < |a|
      invariant 0 <= i < |a|
      invariant i + 1 <= j <= |a|
      invariant forall x, y :: 0 <= x < y < |a| && x < i ==> a[x] <= a[y]
      invariant forall y :: i < y < j ==> a[i] <= a[y]
      decreases |a| - j
    {
      if a[i] > a[j] {
        b := false;
        assert !Sorted(a) by {
          if Sorted(a) {
            assert a[i] <= a[j];
          }
        }
        return;
      }

      assert a[i] <= a[j];
      assert forall y | i < y < j + 1
        ensures a[i] <= a[y]
      {
        if y < j {
          assert a[i] <= a[y];
        } else {
          assert y == j;
        }
      }

      j := j + 1;
    }

    assert forall x, y | 0 <= x < y < |a| && x < i + 1
      ensures a[x] <= a[y]
    {
      if x < i {
        assert a[x] <= a[y];
      } else {
        assert x == i;
        assert i < y < |a|;
        assert a[i] <= a[y];
      }
    }

    i := i + 1;
  }

  b := true;
  assert Sorted(a) by {
    forall x, y | 0 <= x < y < |a|
      ensures a[x] <= a[y]
    {
      assert x < i;
      assert a[x] <= a[y];
    }
  }
}

