lemma BubbleStep(s: seq<int>, j: int, n: int)
  requires AlmostSorted(s, j, n)
  requires 0 < j
  requires s[j - 1] > s[j]
  ensures AlmostSorted(s[j - 1 := s[j]][j := s[j - 1]], j - 1, n)
{
  var t := s[j - 1 := s[j]][j := s[j - 1]];

  forall x, y | 0 <= x < y < j - 1
    ensures t[x] <= t[y]
  {
    assert t[x] == s[x];
    assert t[y] == s[y];
    assert (s[..j])[x] == s[x];
    assert (s[..j])[y] == s[y];
    assert (s[..j])[x] <= (s[..j])[y];
  }
  assert Sorted(t[..j - 1]);

  forall x, y | 0 <= x < y < n - (j - 1)
    ensures (t[j - 1..n])[x] <= (t[j - 1..n])[y]
  {
    var p := j - 1 + x;
    var q := j - 1 + y;

    assert (t[j - 1..n])[x] == t[p];
    assert (t[j - 1..n])[y] == t[q];

    if p == j - 1 {
      assert t[p] == s[j];
      if q == j {
        assert t[q] == s[j - 1];
      } else {
        assert j < q < n;
        assert (s[j..n])[0] == s[j];
        assert (s[j..n])[q - j] == s[q];
        assert (s[j..n])[0] <= (s[j..n])[q - j];
        assert t[q] == s[q];
      }
    } else if p == j {
      assert t[p] == s[j - 1];
      assert j + 1 <= q < n;
      assert s[j - 1] <= s[q];
      assert t[q] == s[q];
    } else {
      assert j < p < q < n;
      assert (s[j..n])[p - j] == s[p];
      assert (s[j..n])[q - j] == s[q];
      assert (s[j..n])[p - j] <= (s[j..n])[q - j];
      assert t[p] == s[p];
      assert t[q] == s[q];
    }
  }
  assert Sorted(t[j - 1..n]);

  forall x, y | 0 <= x < j - 1 && j <= y < n
    ensures t[x] <= t[y]
  {
    assert t[x] == s[x];
    if y == j {
      assert t[y] == s[j - 1];
      assert (s[..j])[x] == s[x];
      assert (s[..j])[j - 1] == s[j - 1];
      assert (s[..j])[x] <= (s[..j])[j - 1];
    } else {
      assert j + 1 <= y < n;
      assert s[x] <= s[y];
      assert t[y] == s[y];
    }
  }

  assert AlmostSorted(t, j - 1, n);
