  ensures multiset(s[j - 1 := s[j]][j := s[j - 1]]) == multiset(s)
{
  var u := s[j - 1 := s[j]];
  assert u[j] == s[j];

  UpdateMultiset(s, j - 1, s[j]);
  UpdateMultiset(u, j, s[j - 1]);

  calc {
    multiset(s[j - 1 := s[j]][j := s[j - 1]]);
    == multiset(u[j := s[j - 1]]);
    == multiset(u) - multiset{u[j]} + multiset{s[j - 1]};
    == (multiset(s) - multiset{s[j - 1]} + multiset{s[j]})
       - multiset{s[j]} + multiset{s[j - 1]};
    == multiset(s);
  }
}

lemma StartAlmostSorted(s: seq<int>, n: int)
  requires 1 <= n <= |s|
  requires Sorted(s[..n - 1])
  ensures AlmostSorted(s, n - 1, n)
{
  assert |s[n - 1..n]| == 1;
  assert Sorted(s[n - 1..n]);
  assert forall x, y ::
    0 <= x < n - 1 && n <= y < n ==> s[x] <= s[y];
}

lemma BubbleStep(s: seq<int>, j: int, n: int)
  requires AlmostSorted(s, j, n)
  requires 0 < j
  requires s[j - 1] > s[j]
  ensures AlmostSorted(s[j - 1 := s[j]][j := s[j - 1]], j - 1, n)
{
  var t := s[j - 1 := s[j]][j := s[j - 1]];

  forall x, y | 0 <= x < y < j - 1
    ensures t[x] <= t[y]
  {
    assert t[x] == s[x];
    assert t[y] == s[y];
    assert (s[..j])[x] == s[x];
    assert (s[..j])[y] == s[y];
    assert (s[..j])[x] <= (s[..j])[y];
  }
  assert Sorted(t[..j - 1]);

  forall x, y | 0 <= x < y < n - (j - 1)
    ensures (t[j - 1..n])[x] <= (t[j - 1..n])[y]
  {
    var p := j - 1 + x;
    var q := j - 1 + y;

    assert (t[j - 1..n])[x] == t[p];
    assert (t[j - 1..n])[y] == t[q];

    if p == j - 1 {
      assert t[p] == s[j];
      if q == j {
        assert t[q] == s[j - 1];
      } else {
        assert j < q < n;
        assert (s[j..n])[0] == s[j];
        assert (s[j..n])[q - j] == s[q];
        assert (s[j..n])[0] <= (s[j..n])[q - j];
        assert t[q] == s[q];
      }
    } else if p == j {
      assert t[p] == s[j - 1];
      assert j + 1 <= q < n;
      assert s[j - 1] <= s[q];
      assert t[q] == s[q];
    } else {
      assert j < p < q < n;
      assert (s[j..n])[p - j] == s[p];
      assert (s[j..n])[q - j] == s[q];
      assert (s[j..n])[p - j] <= (s[j..n])[q - j];
      assert t[p] == s[p];
      assert t[q] == s[q];
    }
  }
  assert Sorted(t[j - 1..n]);

  forall x, y | 0 <= x < j - 1 && j <= y < n
    ensures t[x] <= t[y]
  {
    assert t[x] == s[x];
    if y == j {
      assert t[y] == s[j - 1];
      assert (s[..j])[x] == s[x];
      assert (s[..j])[j - 1] == s[j - 1];
      assert (s[..j])[x] <= (s[..j])[j - 1];
    } else {
      assert j + 1 <= y < n;
      assert s[x] <= s[y];
      assert t[y] == s[y];
    }
  }

  assert AlmostSorted(t, j - 1, n);
}

lemma FinishAlmostSorted(s: seq<int>, j: int, n: int)
  requires AlmostSorted(s, j, n)
  requires j == 0 || s[j - 1] <= s[j]
  ensures Sorted(s[..n])
{
  forall x, y | 0 <= x < y < n
    ensures (s[..n])[x] <= (s[..n])[y]
  {
    assert (s[..n])[x] == s[x];
    assert (s[..n])[y] == s[y];

    if y < j {
      assert (s[..j])[x] == s[x];
      assert (s[..j])[y] == s[y];
      assert (s[..j])[x] <= (s[..j])[y];
    } else if j <= x {
      assert (s[j..n])[x - j] == s[x];
      assert (s[j..n])[y - j] == s[y];
      assert (s[j..n])[x - j] <= (s[j..n])[y - j];
    } else if y == j {
      assert 0 < j;
      if x < j - 1 {
        assert (s[..j])[x] == s[x];
        assert (s[..j])[j - 1] == s[j - 1];
        assert (s[..j])[x] <= (s[..j])[j - 1];
      } else {
        assert x == j - 1;
      }
      assert s[j - 1] <= s[j];
    } else {
      assert 0 <= x < j;
      assert j + 1 <= y < n;
      assert s[x] <= s[y];
    }
  }
}

method InsertionSort(a: array<int>)
  modifies a
  ensures Sorted(a[..])
  ensures multiset(a[..]) == multiset(old(a[..]))
{
  var i := 0;

  while i < a.Length
    invariant 0 <= i <= a.Length
    invariant Sorted(a[..i])
    invariant multiset(a[..]) == multiset(old(a[..]))
    decreases a.Length - i
  {
    StartAlmostSorted(a[..], i + 1);
    var j := i;

    while j > 0 && a[j - 1] > a[j]
      invariant 0 <= j <= i
      invariant AlmostSorted(a[..], j, i + 1)
      invariant multiset(a[..]) == multiset(old(a[..]))
      decreases j
    {
      ghost var s := a[..];

      BubbleStep(s, j, i + 1);
      AdjacentSwapMultiset(s, j);

      var temp := a[j - 1];
      a[j - 1] := a[j];
      a[j] := temp;

      assert a[..] == s[j - 1 := s[j]][j := s[j - 1]];
      j := j - 1;
    }

    assert j == 0 || a[j - 1] <= a[j];
    FinishAlmostSorted(a[..], j, i + 1);
    i := i + 1;
  }
}
