method MergeSorted(a: seq<int>, b: seq<int>) returns (out: seq<int>)
  requires Sorted(a) && Sorted(b)
  ensures Sorted(out)
  ensures multiset(out) == multiset(a) + multiset(b)
{
  var i := 0;
  var j := 0;
  out := [];
  while i < |a| || j < |b|
    invariant 0 <= i <= |a| && 0 <= j <= |b|
    invariant Sorted(out)
    invariant multiset(out) == multiset(a[..i]) + multiset(b[..j])
    invariant forall k :: 0 <= k < |out| ==> (i < |a| ==> out[k] <= a[i]) && (j < |b| ==> out[k] <= b[j])
    decreases |a| - i + |b| - j
  {
    if j == |b| || (i < |a| && a[i] <= b[j]) {
      assert a[..i+1] == a[..i] + [a[i]];
      SortedAppend(out, a[i]);
      var x := a[i];
      out := out + [x];
      i := i + 1;
      assert forall k :: 0 <= k < |out| ==> out[k] <= x;
      assert i < |a| ==> x <= a[i];
    } else {
      assert b[..j+1] == b[..j] + [b[j]];
      SortedAppend(out, b[j]);
      var x := b[j];
      out := out + [x];
      j := j + 1;
      assert forall k :: 0 <= k < |out| ==> out[k] <= x;
      assert j < |b| ==> x <= b[j];
    }
  }
  assert a[..i] == a;
  assert b[..j] == b;
}

