predicate LowerBound(x: int, s: seq<int>)
{
  forall i :: 0 <= i < |s| ==> x <= s[i]
}

lemma TailSorted(s: seq<int>)
  requires |s| > 0
  requires Sorted(s)
  ensures Sorted(s[1..])
{
  forall i, j | 0 <= i < j < |s[1..]|
    ensures s[1..][i] <= s[1..][j]
  {
    assert s[1..][i] == s[i + 1];
    assert s[1..][j] == s[j + 1];
    assert 0 <= i + 1 < j + 1 < |s|;
    assert s[i + 1] <= s[j + 1];
  }
}

lemma HeadLowerBound(s: seq<int>)
  requires |s| > 0
  requires Sorted(s)
  ensures LowerBound(s[0], s)
{
  forall i | 0 <= i < |s|
    ensures s[0] <= s[i]
  {
    if i > 0 {
      assert 0 <= 0 < i < |s|;
      assert s[0] <= s[i];
    }
  }
}

lemma TailLowerBound(x: int, s: seq<int>)
  requires |s| > 0
  requires LowerBound(x, s)
  ensures LowerBound(x, s[1..])
{
  forall i | 0 <= i < |s[1..]|
    ensures x <= s[1..][i]
  {
    assert s[1..][i] == s[i + 1];
    assert 0 <= i + 1 < |s|;
    assert x <= s[i + 1];
  }
}

lemma WeakenLowerBound(x: int, y: int, s: seq<int>)
  requires x <= y
  requires LowerBound(y, s)
  ensures LowerBound(x, s)
{
  forall i | 0 <= i < |s|
    ensures x <= s[i]
  {
    assert y <= s[i];
  }
}

lemma PrependLowerBound(x: int, y: int, s: seq<int>)
  requires x <= y
  requires LowerBound(x, s)
  ensures LowerBound(x, [y] + s)
{
  forall i | 0 <= i < |[y] + s|
    ensures x <= ([y] + s)[i]
  {
    if i == 0 {
      assert ([y] + s)[i] == y;
    } else {
      assert 0 <= i - 1 < |s|;
      assert ([y] + s)[i] == s[i - 1];
      assert x <= s[i - 1];
    }
  }
}

lemma PrependSorted(x: int, s: seq<int>)
  requires Sorted(s)
  requires LowerBound(x, s)
  ensures Sorted([x] + s)
{
  forall i, j | 0 <= i < j < |[x] + s|
    ensures ([x] + s)[i] <= ([x] + s)[j]
  {
    if i == 0 {
      assert ([x] + s)[i] == x;
      assert 0 <= j - 1 < |s|;
      assert ([x] + s)[j] == s[j - 1];
      assert x <= s[j - 1];
    } else {
      assert 0 <= i - 1 < j - 1 < |s|;
      assert ([x] + s)[i] == s[i - 1];
      assert ([x] + s)[j] == s[j - 1];
      assert s[i - 1] <= s[j - 1];
    }
  }
}

method MergeSortedAux(a: seq<int>, b: seq<int>) returns (out: seq<int>)
  requires Sorted(a) && Sorted(b)
  ensures Sorted(out)
  ensures multiset(out) == multiset(a) + multiset(b)
  ensures forall k ::
    LowerBound(k, a) && LowerBound(k, b) ==> LowerBound(k, out)
  decreases |a| + |b|
{
  if |a| == 0 {
    out := b;

    forall k | LowerBound(k, a) && LowerBound(k, b)
      ensures LowerBound(k, out)
    {
    }
  } else if |b| == 0 {
    out := a;

    forall k | LowerBound(k, a) && LowerBound(k, b)
      ensures LowerBound(k, out)
    {
    }
  } else if a[0] <= b[0] {
    TailSorted(a);
    HeadLowerBound(a);
    TailLowerBound(a[0], a);

    HeadLowerBound(b);
    WeakenLowerBound(a[0], b[0], b);

    var rest := MergeSortedAux(a[1..], b);
    assert LowerBound(a[0], rest);

    out := [a[0]] + rest;
    PrependSorted(a[0], rest);

    assert a == [a[0]] + a[1..];
    calc {
      multiset(out);
      == multiset([a[0]]) + multiset(rest);
