         (multiset(a[1..]) + multiset(b));
      == (multiset([a[0]]) + multiset(a[1..])) +
         multiset(b);
      == multiset(a) + multiset(b);
    }

    forall x | LowerBound(x, a) && LowerBound(x, b)
      ensures LowerBound(x, out)
    {
      assert x <= a[0];
      LowerBoundTail(x, a);
      assert LowerBound(x, a[1..]);
      assert LowerBound(x, rest);
      LowerBoundPrepend(x, a[0], rest);
    }
  } else {
    assert b[0] < a[0];

    SortedTail(b);
    var rest := MergeSortedAux(a, b[1..]);

    FirstLowerBound(b);
    LowerBoundTail(b[0], b);
    FirstLowerBound(a);
    LowerBoundTrans(b[0], a[0], a);

    assert LowerBound(b[0], a);
    assert LowerBound(b[0], b[1..]);
    assert LowerBound(b[0], rest);

    PrependSorted(b[0], rest);
    out := [b[0]] + rest;

    SplitHead(b);
    calc {
      multiset(out);
      == multiset([b[0]]) + multiset(rest);
      == multiset([b[0]]) +
         (multiset(a) + multiset(b[1..]));
      == multiset(a) +
         (multiset([b[0]]) + multiset(b[1..]));
      == multiset(a) + multiset(b);
    }

    forall x | LowerBound(x, a) && LowerBound(x, b)
      ensures LowerBound(x, out)
    {
      assert x <= b[0];
      LowerBoundTail(x, b);
      assert LowerBound(x, b[1..]);
      assert LowerBound(x, rest);
      LowerBoundPrepend(x, b[0], rest);
    }
  }
}

