lemma SwapPreservesMultiset(s: seq<int>, i: int, j: int)
  requires 0 <= i < j < |s|
  ensures multiset(s[i := s[j]][j := s[i]]) == multiset(s)
{
  var t := s[i := s[j]][j := s[i]];

  assert s ==
    s[..i] + [s[i]] + s[i + 1..j] + [s[j]] + s[j + 1..];

  assert t ==
    s[..i] + [s[j]] + s[i + 1..j] + [s[i]] + s[j + 1..];

  calc {
    multiset(t);
    ==
      multiset(s[..i]) +
      multiset{s[j]} +
      multiset(s[i + 1..j]) +
      multiset{s[i]} +
      multiset(s[j + 1..]);
    ==
      multiset(s[..i]) +
      multiset{s[i]} +
      multiset(s[i + 1..j]) +
      multiset{s[j]} +
      multiset(s[j + 1..]);
    == multiset(s);
  }
}

method Partition(a: array<int>, pivot: int) returns (k: int)
  modifies a
  ensures 0 <= k <= a.Length
  ensures forall i :: 0 <= i < k ==> a[i] < pivot
  ensures forall i :: k <= i < a.Length ==> a[i] >= pivot
  ensures multiset(a[..]) == multiset(old(a[..]))
{
  k := 0;
  var i := 0;

  while i < a.Length
    invariant 0 <= k <= i <= a.Length
    invariant forall j :: 0 <= j < k ==> a[j] < pivot
    invariant forall j :: k <= j < i ==> a[j] >= pivot
    invariant multiset(a[..]) == multiset(old(a[..]))
    decreases a.Length - i
  {
    if a[i] < pivot {
      if k < i {
        ghost var s := a[..];

        assert forall j :: 0 <= j < k ==> s[j] < pivot;
        assert forall j :: k <= j < i ==> s[j] >= pivot;
        assert s[i] < pivot;
        assert s[k] >= pivot;

        a[k], a[i] := a[i], a[k];

        assert a[..] == s[k := s[i]][i := s[k]];
        SwapPreservesMultiset(s, k, i);
        assert multiset(a[..]) == multiset(s);

        assert a[k] == s[i];
        assert a[i] == s[k];
        assert forall j :: 0 <= j < k ==> a[j] == s[j];
        assert forall j :: k < j < i ==> a[j] == s[j];

        assert forall j :: 0 <= j <= k ==> a[j] < pivot by {
          forall j | 0 <= j <= k
            ensures a[j] < pivot
          {
            if j == k {
              assert a[j] == s[i];
            } else {
              assert 0 <= j < k;
              assert a[j] == s[j];
            }
          }
        }

        assert forall j :: k < j <= i ==> a[j] >= pivot by {
          forall j | k < j <= i
            ensures a[j] >= pivot
          {
            if j == i {
              assert a[j] == s[k];
            } else {
              assert k < j < i;
              assert a[j] == s[j];
            }
          }
        }
      } else {
        assert k == i;
        assert forall j :: 0 <= j <= k ==> a[j] < pivot;
        assert forall j :: k < j <= i ==> a[j] >= pivot;
      }

      k := k + 1;
    } else {
      assert a[i] >= pivot;
    }

    i := i + 1;
  }
}

