  ensures forall i :: 0 <= i <= |a| ==> p[i] == Sum(a[..i])
{
  p := [0];
  var i := 0;

  assert a[..0] == [];
  assert Sum(a[..0]) == 0;

  while i < |a|
    invariant 0 <= i <= |a|
    invariant |p| == i + 1
    invariant forall j :: 0 <= j <= i ==> p[j] == Sum(a[..j])
    decreases |a| - i
